    "description": "中新网广州10月10日电 (记者 郭军)全国经济地理研究会区域协调发展专业委员会第二届年会暨“十五五”时期中国区域协调发展的理论与实践研讨会，10日在暨南大学召开。来自中国科学院、北京大学、武汉大学、南开大学、澳门城市大学、华南师范大学、暨南大学、广东省社会科学院等高校以及科研院所的专家学者与会。",
