    "author": "尚昆仑,杨琳,姜亮,摄制王胜利,摄制陈露",
    "description": "河南方城独树镇烈士陵园烈士史料展厅里，一只旧葫芦瓢静静陈列。这件寻常农家器具，藏着红二十五军和乡亲们的一段往事。 1934年11月25日，红二十五军行军来到方城小史店镇过山庙村。部队在朱家二楼阁楼召开紧急会议，谋划行军路线。战士们告诉乡亲：我们是红军，是老百姓自己的队伍。 看着饥寒交迫的年轻战士，村民十分心疼。村民朱全生家里仅剩半袋黄豆，他的父母打算炒熟送给红军当干粮。推让之间，盛黄豆的葫芦瓢被拉扯撕裂。几番推辞不下，红军战士们暂时接下…",
    "content": "河南方城独树镇烈士陵园烈士史料展厅里，一只旧葫芦瓢静静陈列。这件寻常农家器具，藏着红二十五军和乡亲们的一段往事。 1934年11月25日，红二十五军行军来到方城小史店镇过山庙村。部队在朱家二楼阁楼召开紧急会议，谋划行军路线。战士们告诉乡亲：我们是红军，是老百姓自己的队伍。 看着饥寒交迫的年轻战士，村民十分心疼。村民朱全生家里仅剩半袋黄豆，他的父母打算炒熟送给红军当干粮。推让之间，盛黄豆的葫芦瓢被拉扯撕裂。几番推辞不下，红军战士们暂时接下了黄豆。 当晚寒风刺骨，无论乡亲们怎么挽留，红军战士们始终坚持在屋外的房檐下睡觉…"
