    "description": "新华社巴黎10月10日电（记者吴傲雪 张百慧）2026年联合国教科文组织女童和妇女教育奖颁奖仪式9日在法国巴黎举行，来自摩洛哥和秘鲁的两个项目获奖。 据介绍，摩洛哥“翱翔项目”凭借其“翱翔资源包”项目获奖。该项目帮助摩洛哥及其他地区处境不利的青春期女孩继续接受教育，并为未来发展做好规划。该项目自2017年以来已覆盖5个国家的8000多名青春期女孩。 国际关怀组织秘鲁办事处凭借“女孩机遇”项目获奖。该项目帮助秘鲁农村地区和原住民社区的青春…",
    "content": "新华社巴黎10月10日电（记者吴傲雪 张百慧）2026年联合国教科文组织女童和妇女教育奖颁奖仪式9日在法国巴黎举行，来自摩洛哥和秘鲁的两个项目获奖。 据介绍，摩洛哥“翱翔项目”凭借其“翱翔资源包”项目获奖。该项目帮助摩洛哥及其他地区处境不利的青春期女孩继续接受教育，并为未来发展做好规划。该项目自2017年以来已覆盖5个国家的8000多名青春期女孩。 国际关怀组织秘鲁办事处凭借“女孩机遇”项目获奖。该项目帮助秘鲁农村地区和原住民社区的青春期女孩完成中等教育，并为继续深造和就业拓宽发展路径。自2016年以来，该项目已覆…"
