    "content": "新华社北京10月10日电 题：为购房家庭减负 房贷贴息政策加速落地见效 新华社记者吴雨 10月1日起，居民购房贷款贴息政策在全国正式实施。各家银行迅速行动，第一时间明确服务流程、完善系统功能，让“免申即享”落到实处，助力符合条件的购房家庭尽早享受贴息实惠。 在广州工作多年的陈女士，近日选购了一套92平方米的两居室，向农业银行申请了80万元住房贷款。享受贴息后，预计共节省利息约4万元。“在广州打拼这么多年，终于拥有自己的小家，还赶上贴息好政策，肩上的担子轻了不少。”陈女士说。 陈女士享受的房贷贴息得益于财政部、中国人…"
