    "link": "http://www.news.cn/20261010/f97ef91110a34e06b3ea6f822c1451e5/c.html",
    "pub_date": "2026-10-10 18:01:13",
    "author": "彭菁",
    "description": "9月，江西上犹县五指峰乡受台风“沙德尔”及持续强降雨影响，先后两次发生泥石流。该乡74岁的兼职网格员曾仁连在12天内两次成功预警，为群众转移赢得先机。 第一次是9月6日，他发现河水浑浊、树木异常摇摆，上报后291人及时转移；第二次是9月17日，他察觉山体异响、出现裂缝，连夜组织436人撤离。两次泥石流均未造成人员伤亡。 日前，曾仁连被应急管理部风险监测和火灾综合防治司通报表扬。 作者：彭菁、钟先东 新华社音视频部制作",
