    "pub_date": "2026-10-10 17:59:54",
    "author": "",
    "description": "调整后，佛山站列车停靠将增至115列，运力规模显著提升。此次新增多趟始发终到列车，首次开行佛山至武汉、上海南、北京西等多趟列车，全方位拓宽佛山对外高铁出行版图。针对粤西片区早高峰出行需求，本次调图重点补强8时前早班运力，提前粤西片区早高峰出行体验。本次调图还通过延长多趟列车运行区段、调整部分车次编号，进一步扩大铁路服务覆盖范围。（央视新闻）",
