    "content": "36氪获悉，乘联分会发布数据，9月1-30日，全国乘用车市场市场零售170.2万辆，同比去年9月同期下降24%，较上月同期增长10%，今年以来乘用车累计零售1,341.8万辆，同比下降21%；9月1-30日，全国乘用车新能源市场零售114.1万辆，同比去年9月同期下降12%，较上月同期增长14%，今年以来累计零售781.6万辆，同比下降12%；9月1-30日，全国乘用车新能源市场零售渗透率67.1%；9月1-30日，全国乘用车新能源厂商批发渗透率66.1%。"
