    "content": "中新网重庆10月10日电 (马佳欣)“我们将积极融入巴蜀文化旅游走廊，打造‘龙灯、龙舞、龙温泉、龙马、龙舟、龙足球’六大品牌。”10日，铜梁区委副书记周永刚在“开局起步十五五·建设现代化新重庆”系列主题新闻发布会铜梁专场上表示，“十五五”期间，铜梁将推动龙文化旅游名城建设，全面唱响“中华龙乡·重庆铜梁”。"
