    "content": "新华社北京10月10日电 工业和信息化部等四部门10日公开发布关于进一步加强汽车产品创新设计和研发测试验证有关管理工作的通知（征求意见稿）。汽车产品创新设计技术指南围绕虚拟操纵件、门把手、新型人机交互系统、大角度座椅等方面提出具体测试验证要求。 根据汽车产品创新设计技术指南，汽车生产企业应当将安全风险评估前置，在产品研发设计阶段，对有关创新设计进行复杂工况、极端场景下的失效模式分析，充分识别潜在安全风险，评估不达标的创新设计，不得装车应用等。 具体要求包括，汽车应急逃生装置、应急制动装置、驱动系统电源切断装置等涉及…"
