    "content": "新华社北京10月10日电 针对赖清德10日在台北发表所谓“双十”讲话中有关两岸关系内容，国务院台办发言人张晗答问表示，赖清德的讲话，罔顾事实、颠倒是非，误导民众、用心叵测，是其作为“务实台独工作者”的“本色表演”。其在讲话中顽固抱持“台独”分裂思维，渲染“大陆威胁”，鼓吹“民主对抗威权”虚假叙事，妄图“以武谋独”、“倚外谋独”，挑动两岸对立对抗，破坏台海和平稳定。 她表示，世界上只有一个中国，台湾是中国的一部分，这是真正的台海现状。一个中国原则是国际关系基本准则和国际社会普遍共识，也是二战后国际秩序的重要组成部分。…"
