    "content": "由中国华侨华人研究所组织编写的《世界侨情报告（2026）》一书日前由社会科学文献出版社出版。全书共36.8万余字，分为总报告、区域篇、国别篇三部分，共20章。 《世界侨情报告（2026）》书封。 该书是中国华侨华人研究所组织编写的第5部《世界侨情报告》，系统分析了2023年至2025年世界侨情状况，在延续按照区域、国别梳理侨情的基础上，着重加强对当前重大侨情变化的分析研判，厘清华侨华人在中国式现代化中的作用，以对中国有利、住在国有利、华侨华人有利的视角，鼓励华侨华人加强与其他族群的交流与合作，以相同的利益诉求团结其…"
