    "content": "新华社西安10月10日电（记者刘彤）10月10日，由中铁第一勘察设计院集团有限公司勘察设计、中铁十八局承建的神瓦铁路黄河特大桥顺利合龙。作为神瓦铁路全线唯一一座跨越黄河的桥梁，它的合龙标志着这条陕晋能源大通道的重难点控制性工程取得关键突破，为项目全面建设按下了“快进键”。 神木至瓦塘铁路正线全长75.17公里，设计时速120公里，是连接陕西神木与山西兴县瓦塘镇的国家一级单线电气化铁路。本次合龙的黄河特大桥总长1030.04米，依次跨越沿黄观光公路、黄河主河槽及S249省道，其中连续梁最大跨度138米，桥面距水面达6…"
