    "description": "新华社乌鲁木齐10月10日电 题：赋能科技兴疆 第三次新疆综合科学考察成果丰硕 新华社记者潘莹、古扎丽努尔 10月10日，第三次新疆综合科学考察十大进展在乌鲁木齐发布。历时5年、汇集全国46家科研单位、科考队员累计参与达6000余人次，本次科考针对新疆生态环境、土地农业、生物多样性与生物资源、矿产能源、水资源等领域开展综合调查研究，取得重要进展。 “本次考察产出多项原创性、突破性成果，全面更新新疆生态环境本底科学认知，为新疆社会稳定和长…",
    "content": "新华社乌鲁木齐10月10日电 题：赋能科技兴疆 第三次新疆综合科学考察成果丰硕 新华社记者潘莹、古扎丽努尔 10月10日，第三次新疆综合科学考察十大进展在乌鲁木齐发布。历时5年、汇集全国46家科研单位、科考队员累计参与达6000余人次，本次科考针对新疆生态环境、土地农业、生物多样性与生物资源、矿产能源、水资源等领域开展综合调查研究，取得重要进展。 “本次考察产出多项原创性、突破性成果，全面更新新疆生态环境本底科学认知，为新疆社会稳定和长治久安，以及服务国家战略全局提供科技支撑。”第三次新疆综合科学考察工作组组长肖文…"
