    "content": "新华社北京10月10日电（记者张晓洁、王聿昊）记者从国新办10月10日举行的“开局起步‘十五五’”系列主题新闻发布会上获悉，新就业形态人员职业伤害保障试点开展以来，制度运行总体平稳，试点范围不断扩大，参保人数不断增多。截至9月底，职业伤害保障试点累计参保3727万人。截至目前，参保单数达1087亿单。 人力资源社会保障部新闻发言人、副部长李忠介绍，截至9月底，全国基本养老保险、失业保险、工伤保险参保人数分别达到10.79亿人、2.51亿人、3.27亿人，三项社会保险基金累计结余11.2万亿元。 “下一步，我们将统筹…"
