    "content": "新华社昆明10月10日电（记者何春好、庄北宁）记者近日从南方电网云南电网公司获悉，该公司依托国家计量数据建设应用中心（绿色电力），联合云南省消防救援局研发应用电动自行车室内充电风险智能识别系统，利用电力大数据治理电动自行车违规入户充电。目前已在昆明、丽江、怒江等地50余个小区试点应用，已累计识别疑似户内充电用户14000余次，试点小区经治理，电动自行车集中充电桩使用率提升，违规充电事件明显减少。 “昆明市呈贡区5个小区内，连续出现居民用户用电功率特征比对异常，疑似频发电动自行车违规接入充电行为，请开展处置。”不久前…"
