    "content": "第二十九届北京国际音乐节开幕音乐会10月9日晚在国家大剧院上演。指挥家夏尔·迪图瓦执棒北京国际音乐节节日乐团，以莫扎特的降E大调第二十二钢琴协奏曲与雷斯庇基的罗马三部曲，奏响本届音乐节的序章。 第二十九届北京国际音乐节开幕音乐会现场。（主办方供图） 第二十九届北京国际音乐节以“京华·协奏”为主题，于10月9日至10月20日在北京举行。音乐节期间，伦敦爱乐乐团将作为驻节乐团带来歌剧《魔笛》及系列音乐会，小提琴家宁峰将携手德国波茨坦室内乐团演绎莫扎特五部小提琴协奏曲。此外，亨德尔歌剧《朱利奥·凯撒》、阿努什卡·香卡专场…"
