    "description": "新华社北京10月10日电 巴西检察部门9日对国际能源巨头壳牌集团在巴西的子公司提起诉讼，要求该公司就2024年巴西南部洪灾相关损失赔偿1.08亿美元，理由是壳牌应对排放温室气体、加剧气候变化所致损失承担责任。 2024年4月底，巴西南部“粮仓”南里奥格兰德州开始连降暴雨，引发严重洪灾，截至同年6月造成近200人死亡、50万人流离失所，导致严重经济损失。检方认为，壳牌集团长期在化石燃料勘探、生产和销售过程中排放温室气体，其历史排放量约占全…",
    "content": "新华社北京10月10日电 巴西检察部门9日对国际能源巨头壳牌集团在巴西的子公司提起诉讼，要求该公司就2024年巴西南部洪灾相关损失赔偿1.08亿美元，理由是壳牌应对排放温室气体、加剧气候变化所致损失承担责任。 2024年4月底，巴西南部“粮仓”南里奥格兰德州开始连降暴雨，引发严重洪灾，截至同年6月造成近200人死亡、50万人流离失所，导致严重经济损失。检方认为，壳牌集团长期在化石燃料勘探、生产和销售过程中排放温室气体，其历史排放量约占全球历史排放总量的2%，公司应根据其对全球变暖的影响承担相应的环境和气候责任。 据…"
