    "content": "西藏金融监管局日前发布公示，金融是特许经营行业，必须持牌经营。根据《国务院关于实施金融控股公司准入管理的决定》（国发〔2020〕4号）等有关规定，未经批准不得登记为金融控股公司，不得在公司名称中使用“金融控股”“金融集团”“金控”等字样。西藏金融监管局会同市场监管部门对辖内涉金融经营主体进行全面摸排，经综合研判。认定西藏辖内存在3家名称未经批准含有“金融控股”“金融集团”“金控”等字样的经营主体，分别是：1.拉萨经济技术开发区亦兴金控投资有限公司；2.西藏金控信息服务有限公司；3.西藏金控基金管理有限公司。（央视新…"
