    "author": "",
    "description": "36氪获悉，天眼查App显示，近日，北京新华顺航商贸有限公司发生工商变更，新增海南航空控股股份有限公司为股东，同时，注册资本由30万元人民币增至约22亿元人民币，增幅约733333%。该公司成立于2010年7月，法定代表人为王新，经营范围为销售日用品、电子产品、装饰材料、五金交电、办公设备、服装鞋帽，家居装饰，现由中国新华航空集团有限公司及上述新增股东共同持股。",
