    "content": "前两天刷推刷到一条帖子，说 COD 僵尸、Halo 、Skate 3 现在都能直接在浏览器里玩，配了张 24 个游戏的拼图，浏览量 600 多万。 我第一反应是不太信，于是花了一天把评论区给的链接一个个点开看了。结果大概是这样： Quake 三部曲、德军总部（ RTCW ）、半条命、暗黑破坏神这几个是真能玩的，开源引擎编译成 wasm ，跑的是官方当年放出来的试玩版数据。Halo CE 和罪恶都市也能跑，但得自己导入正版游戏文件。 Skate 3 比较狠，作者用 Rust 把引擎重写了一遍，贴图、模型、音效全部重新…"
