    "content": "保健品卖不动了？ 近期发布的《抖音银发市场线上消费与广告投放报告》显示，50岁以上网民规模达3.76亿，占全体网民33.5%。在这一群体的消费偏好榜单上，鲜花园艺以126.4的偏好指数遥遥领先，酒类、生鲜、珠宝文玩紧随其后；而 曾经被视作银发消费标配的滋补保健品，已然跌出消费偏好前四名。 不少人由此产生疑问：难道中老年群体正在放弃健康消费？ 答案显然是否定的。事实上，银发群体的健康消费并非在收缩，而是在升级：他们不再满足于笼统的滋补概念，而是更倾向于选择可感知、可追踪、能回应个体身体状态的营养服务。 就在传统滋补品…"
